from __future__ import annotations

from dataclasses import dataclass


def _require_non_empty(label: str, value: str) -> None:
    if not value.strip():
        raise ValueError(f"{label} required")


@dataclass(frozen=True)
class MeterReading:
    asset_id: str
    previous_value: int
    current_value: int
    rollover_point: int
    reading_minute: int

    def __post_init__(self) -> None:
        _require_non_empty("asset_id", self.asset_id)
        if self.previous_value < 0:
            raise ValueError("previous_value must be non-negative")
        if self.current_value < 0:
            raise ValueError("current_value must be non-negative")
        if self.rollover_point <= 0:
            raise ValueError("rollover_point must be positive")
        if self.previous_value >= self.rollover_point:
            raise ValueError("previous_value must be below rollover_point")
        if self.current_value >= self.rollover_point:
            raise ValueError("current_value must be below rollover_point")
        if self.reading_minute < 0:
            raise ValueError("reading_minute must be non-negative")

    def reading_span(self) -> tuple[int, int]:
        return (self.previous_value, self.current_value)


@dataclass(frozen=True)
class PreventiveMaintenanceRule:
    pm_id: str
    frequency_units: int
    priority: str

    def __post_init__(self) -> None:
        _require_non_empty("pm_id", self.pm_id)
        if self.frequency_units <= 0:
            raise ValueError("frequency_units must be positive")
        _require_non_empty("priority", self.priority)

    def backlog_label(self) -> str:
        return f"{self.pm_id}:{self.frequency_units}u"


def rule_frequency_check(usage: int, frequency_units: int) -> bool:
    return usage >= frequency_units


def remaining_before_pm(usage: int, frequency_units: int) -> int:
    return max(0, frequency_units - usage)


def is_urgent_priority(priority: str) -> bool:
    return priority.strip().lower() == "urgent"


def asset_display_name(asset_id: str) -> str:
    return asset_id.strip()


def pm_priority_requires_callback(priority: str) -> bool:
    return is_urgent_priority(priority)


def validate_meter_pair(previous_value: int, current_value: int, rollover_point: int) -> None:
    if previous_value >= rollover_point or current_value >= rollover_point:
        raise ValueError("readings must be below rollover_point")


def frequency_gap(usage: int, frequency_units: int) -> int:
    return frequency_units - usage


def rule_matches_asset(_rule: PreventiveMaintenanceRule, _asset_id: str) -> bool:
    """Placeholder for multi-asset PM routes; single-rule batching uses one PM for all assets here."""
    return True

