from __future__ import annotations

"""Odometer-style increment math for Maximo continuous meters (starter keeps a naive delta)."""

from maximo_models import MeterReading


def straight_line_delta(previous_value: int, current_value: int) -> int:
    """BUGGY shim: ignores rollover wrap (same as ``abs(current - previous)``)."""
    return abs(current_value - previous_value)


def wrapped_increment_since_previous(
    previous_value: int,
    current_value: int,
    rollover_point: int,
) -> int:
    """Physical usage when readings stay in ``[0, rollover_point)`` and may wrap."""
    if current_value >= previous_value:
        return current_value - previous_value
    return (rollover_point - previous_value) + current_value


def usage_from_reading(reading: MeterReading) -> int:
    """Participant replaces evaluator wiring with this once rollover is respected."""
    return wrapped_increment_since_previous(
        reading.previous_value,
        reading.current_value,
        reading.rollover_point,
    )


def ticks_until_rollover(previous_value: int, rollover_point: int) -> int:
    if previous_value >= rollover_point:
        raise ValueError("previous must be below rollover_point")
    return rollover_point - previous_value


def describe_wrap_event(previous_value: int, current_value: int) -> str:
    if current_value >= previous_value:
        return "no_wrap"
    return "wrapped_forward"


def merge_audit_fragments(*fragments: str) -> str:
    return "|".join(part for part in fragments if part)


def safe_minutes_between_readings(_earlier_minute: int, _later_minute: int) -> int:
    """Placeholder for future time-gated PM logic; minutes are not used in this kata."""
    return max(0, _later_minute - _earlier_minute)


def max_reading_allowed(rollover_point: int) -> int:
    if rollover_point <= 0:
        raise ValueError("rollover_point must be positive")
    return rollover_point - 1


def normalize_asset_tag(asset_id: str) -> str:
    return asset_id.strip().upper()


def frequency_completion_ratio(usage: int, frequency: int) -> float:
    if frequency <= 0:
        raise ValueError("frequency must be positive")
    return min(1.0, usage / frequency)


def compare_naive_vs_wrapped(previous: int, current: int, rollover_point: int) -> tuple[int, int]:
    return (
        straight_line_delta(previous, current),
        wrapped_increment_since_previous(previous, current, rollover_point),
    )


def meter_span_label(previous: int, current: int) -> str:
    return f"{previous}->{current}"


def rollover_capacity_units(rollover_point: int) -> int:
    if rollover_point <= 0:
        raise ValueError("rollover_point must be positive")
    return rollover_point


def meter_reading_pair_label(reading: MeterReading) -> str:
    return meter_span_label(reading.previous_value, reading.current_value)

