from __future__ import annotations

"""Preview Maximo-style meter-based preventive maintenance without touching Maximo APIs."""

from maximo_models import MeterReading, PreventiveMaintenanceRule, remaining_before_pm, rule_frequency_check
from meter_arithmetic import straight_line_delta

PM_REASON_FREQUENCY_MET = "frequency_met"
PM_REASON_FREQUENCY_NOT_MET = "frequency_not_met"

SUMMARY_FIELDS = (
    "evaluated_count",
    "work_order_count",
    "rollover_asset_ids",
    "generated_asset_ids",
    "results",
)


def summary_field_count() -> int:
    return len(SUMMARY_FIELDS)


def decision_tuple(reading: MeterReading, rule: PreventiveMaintenanceRule) -> tuple[str, str]:
    """Lightweight tuple for logging bridges (not used by starter tests)."""
    return (reading.asset_id, rule.pm_id)


def _measured_usage(reading: MeterReading) -> int:
    # Participant: replace with wrapped increment math (see meter_arithmetic.wrapped_increment_since_previous).
    return straight_line_delta(reading.previous_value, reading.current_value)


def evaluate_meter_pm(
    reading: MeterReading,
    rule: PreventiveMaintenanceRule,
) -> dict[str, object]:
    usage_units = _measured_usage(reading)
    should_generate = rule_frequency_check(usage_units, rule.frequency_units)
    remaining_units = remaining_before_pm(usage_units, rule.frequency_units)
    reason = PM_REASON_FREQUENCY_MET if should_generate else PM_REASON_FREQUENCY_NOT_MET

    return {
        "asset_id": reading.asset_id,
        "pm_id": rule.pm_id,
        "should_generate_work_order": should_generate,
        "work_order_priority": rule.priority if should_generate else None,
        "usage_units": usage_units,
        "remaining_units": remaining_units,
        "rollover_detected": reading.current_value < reading.previous_value,
        "reason": reason,
    }


def summarize_pm_preview(results: list[dict[str, object]]) -> dict[str, object]:
    generated = [result for result in results if result["should_generate_work_order"]]
    rollover_assets = [result["asset_id"] for result in results if result["rollover_detected"]]
    return {
        "evaluated_count": len(results),
        "work_order_count": len(generated),
        "rollover_asset_ids": rollover_assets,
        "generated_asset_ids": [result["asset_id"] for result in generated],
        "results": results,
    }


def preview_has_generated_work_orders(summary: dict[str, object]) -> bool:
    return int(summary["work_order_count"]) > 0


def extract_usage_sequence(results: list[dict[str, object]]) -> list[int]:
    return [int(row["usage_units"]) for row in results]


class MaximoMeterPmEvaluator:
    """Binds a single PM frequency + priority to a batch of meter imports."""

    def __init__(self, rule: PreventiveMaintenanceRule) -> None:
        self.rule = rule

    def evaluate(self, readings: list[MeterReading]) -> dict[str, object]:
        """Evaluate readings in order; summary order mirrors input order."""
        per_reading = [evaluate_meter_pm(reading, self.rule) for reading in readings]
        return summarize_pm_preview(per_reading)

